export async function GET(
  request: Request,
  { params }: { params: { folder: string; mail_id: string } }
) {
  const { folder, mail_id } = await params

  const folderMessages = messagesByFolder[folder] || []
  const random = Math.floor(Math.random() * 14) + 1
  const mail =
    folderMessages.find((msg) => msg.id === mail_id) ||
    folderMessages.find((msg) => Number(msg.id) === random) //random id between 1 and 14, if the mail content is not found (for demo only)

  if (!mail) {
    return NextResponse.json({ error: 'Mail not found' }, { status: 404 })
  }

  return NextResponse.json(mail)
}

export async function OPTIONS() {
  return NextResponse.json({ allow: ['GET'] }, { status: 200 })
}
